/**
 * common-foods.js — built-in library of everyday foods (fork addition).
 *
 * 174 foods from USDA's National Nutrient Database for Standard Reference
 * (SR28; public domain), with USDA's own household portions ("1 medium",
 * "1 cup", "1 slice"). Works offline and instantly; no API key. The data
 * file is generated by scripts/build-common-foods.py (see FORK.md).
 *
 * Exports:
 *   searchCommonFoods(query, limit)  → ranked library entries
 *   commonFoodToFood(entry, idx)     → an app food (per serving, alt units)
 *   foodEmoji(name)                  → an emoji for a food name, or ''
 */
import DATA from './common-foods-data.js';

export const COMMON_FOODS = DATA;

const _norm = (s) => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9% ]+/g, ' ')
  .replace(/\s+/g, ' ').trim();
// "berries" → "berry", "tomatoes" → "tomato", "eggs" → "egg"
const _stem = (w) => w.length > 4 && w.endsWith('ies') ? w.slice(0, -3) + 'y'
  : w.length > 4 && /(ches|shes|xes|oes)$/.test(w) ? w.slice(0, -2)
  : w.length > 3 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w;
const _toks = (s) => _norm(s).split(' ').filter(Boolean).map(_stem);

const _index = DATA.map((e) => {
  const names = [e.name, ...(e.aliases || [])];
  return { e, names: names.map(_norm), toks: names.map(_toks) };
});

/** Ranked matches for a search box query. Empty query → []. */
export function searchCommonFoods(query, limit = 8) {
  return searchCommonFoodsScored(query, limit).map(x => x.entry);
}

/** Same, with scores: 100 exact, ~65-85 name/prefix, 40 partial. */
export function searchCommonFoodsScored(query, limit = 8) {
  const q = _norm(query);
  if (!q) return [];
  const qt = _toks(q);
  const out = [];
  for (const { e, names, toks } of _index) {
    let best = 0;
    names.forEach((n, i) => {
      const t = toks[i];
      let s = 0;
      if (n === q || t.join(' ') === qt.join(' ')) s = 100;
      else if (n.startsWith(q)) s = 85 - Math.min(20, n.length - q.length);
      else if (qt.every(w => t.some(x => x.startsWith(w)))) s = 70 - Math.min(20, t.length);
      else if (qt.length > 1 && qt.filter(w => t.some(x => x.startsWith(w))).length >= qt.length - 1 && qt[0].length > 3) s = 40;
      if (i > 0) s -= 3;              // aliases rank just under the real name
      best = Math.max(best, s);
    });
    if (best > 0) out.push({ e, s: best });
  }
  out.sort((a, b) => b.s - a.s || a.e.name.length - b.e.name.length);
  return out.slice(0, limit).map(x => ({ entry: x.e, score: x.s }));
}

const _round = (n, d = 1) => Math.round(n * 10 ** d) / 10 ** d;
const _MASS = new Set(['g', 'gram', 'grams', 'kg', 'oz', 'ounce', 'lb', 'pound']);

/** "1 medium (7\" long)" → { amount: 1, unit: 'medium' }; "½ avocado" → 0.5. */
export function parseServingLabel(label) {
  const s = String(label || '').replace('½', '0.5').replace('¼', '0.25').trim();
  const m = /^(\d+(?:\.\d+)?)\s+(.*)$/.exec(s);
  const amount = m ? parseFloat(m[1]) : 1;
  let unit = (m ? m[2] : s).replace(/\(.*?\)/g, '').replace(/\s+/g, ' ').trim();
  unit = unit.replace(/[,;]\s*$/, '');
  // "breast, bone and skin removed" → "breast"; keep short ones ("cup, sliced").
  const comma = unit.indexOf(',');
  if (comma > 0 && unit.length - comma > 12) unit = unit.slice(0, comma);
  unit = unit.slice(0, 28) || 'serving';
  return { amount: amount > 0 ? amount : 1, unit };
}

/**
 * A library entry as an app food, measured in one of its USDA portions
 * (default: the entry's defaultServing). Nutrition is for that portion;
 * every portion becomes an alt unit so the amount picker offers them all.
 * Carbs exclude fiber, matching how the app stores USDA search results.
 */
export function commonFoodToFood(entry, servingIdx = entry?.defaultServing ?? 0) {
  const servings = entry.servings || [];
  const sv = servings[servingIdx] || null;
  const { amount, unit } = sv ? parseServingLabel(sv.label) : { amount: 100, unit: 'g' };
  const grams = sv ? sv.grams : 100;
  const f = grams / 100;
  const n = {};
  for (const [k, v] of Object.entries(entry.per100g || {})) n[k] = _round(v * f, k === 'calories' ? 0 : 2);
  if (n.carbohydrates != null && n.fiber != null) {
    n.carbohydrates = _round(Math.max(n.carbohydrates - n.fiber, n.sugars || 0), 2);
  }
  const alt = [];
  const seen = new Set();
  for (const s of servings) {
    const p = parseServingLabel(s.label);
    const key = p.unit.toLowerCase();
    if (_MASS.has(key) || seen.has(key)) continue;
    seen.add(key);
    alt.push({ abbr: p.unit, grams: _round(s.grams / p.amount, 2) });
  }
  return {
    name: entry.name,
    brand: 'USDA',
    barcode: '',
    portion: unit === 'g' ? grams : amount,
    unit: _MASS.has(unit.toLowerCase()) && unit.toLowerCase() !== 'g' ? unit.toLowerCase() : unit,
    quantity: 1,
    imgUrl: '',
    categories: [],
    nutrition: n,               // per the portion above (not per 100 g), so no nutrition_basis
    alt_units: alt,
    notes: `USDA: ${entry.usda}`,
    icon: entry.icon,
    dateTime: new Date().toISOString(),
    _source: 'common',
    _commonId: entry.id,
  };
}

/* ── Food emoji ─────────────────────────────────────────────────────── */
// Library names/aliases first, then everyday dishes the library doesn't
// carry. Longer keys win ("ice cream" before "cream", "hot dog" before "dog").
const _EXTRA = {
  'ice cream sandwich': '🍨', 'ice cream': '🍨', 'hot dog': '🌭', 'milk tea': '🧋', 'boba': '🧋', 'bubble tea': '🧋',
  'pizza': '🍕', 'burger': '🍔', 'sandwich': '🥪', 'sub': '🥪', 'wrap': '🌯', 'burrito': '🌯',
  'taco': '🌮', 'quesadilla': '🌮', 'nacho': '🌮', 'salad': '🥗', 'soup': '🍲', 'stew': '🍲', 'chili': '🌶️',
  'curry': '🍛', 'sushi': '🍣', 'sashimi': '🍣', 'ramen': '🍜', 'pho': '🍜', 'noodle': '🍜', 'udon': '🍜',
  'dumpling': '🥟', 'gyoza': '🥟', 'bao': '🥟', 'fried rice': '🍚', 'rice': '🍚', 'pasta': '🍝', 'spaghetti': '🍝',
  'lasagna': '🍝', 'steak': '🥩', 'beef': '🥩', 'pork': '🥩', 'lamb': '🥩', 'chicken': '🍗', 'turkey': '🦃',
  'fish': '🐟', 'salmon': '🐟', 'tuna': '🐟', 'shrimp': '🍤', 'crab': '🦀', 'lobster': '🦞', 'egg': '🥚',
  'omelet': '🍳', 'omelette': '🍳', 'bacon': '🥓', 'sausage': '🌭', 'cheese': '🧀', 'bread': '🍞', 'toast': '🍞',
  'bagel': '🥯', 'croissant': '🥐', 'cronut': '🥐', 'pastry': '🥐', 'muffin': '🧁', 'cupcake': '🧁', 'cake': '🍰',
  'cheesecake': '🍰', 'pie': '🥧', 'donut': '🍩', 'doughnut': '🍩', 'cookie': '🍪', 'brownie': '🍫',
  'chocolate': '🍫', 'candy': '🍬', 'gummy': '🍬', 'pancake': '🥞', 'waffle': '🧇', 'cereal': '🥣',
  'oatmeal': '🥣', 'granola': '🥣', 'yogurt': '🥣', 'smoothie': '🥤', 'shake': '🥤', 'protein shake': '🥤',
  'soda': '🥤', 'coffee': '☕', 'latte': '☕', 'espresso': '☕', 'cappuccino': '☕', 'americano': '☕',
  'tea': '🍵', 'matcha': '🍵', 'kombucha': '🍵', 'juice': '🧃', 'lemonade': '🍋', 'water': '💧',
  'beer': '🍺', 'wine': '🍷', 'cocktail': '🍸', 'margarita': '🍸', 'milk': '🥛', 'fries': '🍟',
  'chips': '🥔', 'popcorn': '🍿', 'pretzel': '🥨', 'nuts': '🥜', 'peanut': '🥜', 'fruit': '🍎', 'berry': '🫐',
  'veggie': '🥦', 'vegetable': '🥦', 'bar': '🍫', 'protein bar': '🍫', 'jerky': '🥩', 'tofu': '🧈',
};
let _emojiKeys = null;
function _buildEmoji() {
  const m = new Map();
  for (const e of DATA) {
    for (const n of [e.name, ...(e.aliases || [])]) {
      const k = _toks(n.split(',')[0]).join(' ');
      if (k && !m.has(k)) m.set(k, e.icon);
    }
  }
  for (const [k, v] of Object.entries(_EXTRA)) {
    const kk = _toks(k).join(' ');
    if (!m.has(kk)) m.set(kk, v);
  }
  _emojiKeys = [...m.entries()].sort((a, b) => b[0].length - a[0].length);
}

// What the thing IS beats what's in it: "pineapple pizza" is a pizza,
// "croissant sandwich" a sandwich, "lemon iced tea" a tea.
const _DISHES = ['ice cream sandwich', 'milk tea', 'bubble tea', 'boba', 'protein shake', 'protein bar',
  'pizza', 'burger', 'cheeseburger', 'hamburger', 'sandwich', 'sub', 'wrap', 'burrito', 'taco', 'quesadilla',
  'salad', 'soup', 'stew', 'curry', 'sushi', 'ramen', 'pho', 'noodle', 'dumpling', 'fried rice', 'pasta',
  'lasagna', 'omelet', 'omelette', 'pancake', 'waffle', 'cereal', 'oatmeal', 'smoothie', 'shake', 'cake',
  'cupcake', 'muffin', 'pie', 'donut', 'doughnut', 'cookie', 'brownie', 'cronut', 'croissant', 'bagel',
  'coffee', 'latte', 'espresso', 'cappuccino', 'americano', 'tea', 'matcha', 'kombucha', 'juice',
  'lemonade', 'soda', 'cola', 'beer', 'wine', 'cocktail', 'margarita', 'water', 'fries', 'chips', 'popcorn',
  'hot dog', 'nugget', 'tender', 'wing'];
let _dishKeys = null;

/** An emoji for a food name, or '' when nothing fits. */
export function foodEmoji(name, icon) {
  if (icon) return icon;
  const t = ` ${_toks(name).join(' ')} `;
  if (t.trim() === '') return '';
  if (!_emojiKeys) _buildEmoji();
  if (!_dishKeys) {
    const m = new Map(_emojiKeys);
    _dishKeys = _DISHES.map(d => _toks(d).join(' ')).filter(k => m.has(k) || _EXTRA[k])
      .map(k => [k, m.get(k) || _EXTRA[k]]).sort((a, b) => b[0].length - a[0].length);
  }
  // The dish word that appears LAST names the thing ("chicken salad
  // sandwich" → sandwich), so pick the dish match furthest right.
  // Ties (same end) go to the longer phrase: "ice cream sandwich" > "sandwich".
  let best = null, end = -1, len = 0;
  for (const [k, v] of _dishKeys) {
    const i = t.lastIndexOf(` ${k} `);
    if (i < 0) continue;
    const e = i + k.length;
    if (e > end || (e === end && k.length > len)) { end = e; len = k.length; best = v; }
  }
  if (best) return best;
  for (const [k, v] of _emojiKeys) {
    if (t.includes(` ${k} `)) return v;
  }
  return '';
}
